import json, subprocess, urllib.request

SNAP = '41879d00a'  # our snapshot commit

def sha(s):
    return subprocess.run(['git','rev-parse',s],capture_output=True,text=True).stdout.strip()

def is_ancestor(a,b):
    return subprocess.run(['git','merge-base','--is-ancestor',a,b]).returncode==0

import json
ids=[v['id'] for v in json.load(open('/tmp/osv_list.json'))['results'][0]['vulns']]
for vid in ids:
    d=json.load(urllib.request.urlopen(f'https://api.osv.dev/v1/vulns/{vid}'))
    det=(d.get('details') or '')
    lines=[l for l in det.splitlines()]
    state=[]
    cap=False
    for l in det.splitlines():
        if 'Crash state:' in l: cap=True; continue
        if cap:
            if l.strip().startswith('```'): break
            if l.strip(): state.append(l.strip())
    intro=fix=None
    for a in d.get('affected',[]):
        for r in a.get('ranges',[]):
            for e in r.get('events',[]):
                if 'introduced' in e and intro is None: intro=e['introduced']
                if 'fixed' in e and fix is None: fix=e['fixed']
    # reachability: is introduced commit an ancestor of snapshot?
    reach='?'
    try:
        reach = 'YES' if is_ancestor(intro,SNAP) else 'no'
    except Exception as ex:
        reach='ERR'
    print(f"{vid} intro_in_snap={reach}")
    print(f"   summary: {d.get('summary')}")
    print(f"   crash: {' | '.join(state[:3])}")
EOF

